#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
# Outside the repository, so a key can't be committed by accident. bin/exif-dater.js reads the same file.
ENV_FILE="${XDG_CONFIG_HOME:-$HOME/.config}/exif-dater/env"
# uv and ant install here, and a new install isn't on PATH until the next login.
PATH="$HOME/.local/bin:$PATH"

# The Claude CLI release used for browser sign-in. Change the version and both checksums together.
ANT_VERSION=2.14.0
ANT_SHA256_AMD64=5a63b771bc9f9658e38865cede2077e0562757a4555e0cf241390d52beaedd55
ANT_SHA256_ARM64=fea08806588183f0db8cd01832ad2056cc743807a9d3b1608e117eb53f38741c

# Remember a key that came from the shell, because it overrides everything saved here.
SHELL_KEY="${ANTHROPIC_API_KEY:+yes}"

have() { command -v "$1" >/dev/null 2>&1; }
done_ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
todo() { SKIPPED+=("$1"); warn "$1"; }

apt_install() {
  if ! have apt-get; then
    warn "This wizard installs with apt-get, which isn't on this system."
    return 1
  fi
  confirm "Run 'sudo apt-get install $*'?" || return 1
  sudo apt-get update || warn "apt-get update reported problems, trying the install anyway"
  sudo apt-get install -y "$@"
}

node_ready() {
  have node && have npx && node -e 'process.exit(parseInt(process.versions.node, 10) >= 20 ? 0 : 1)'
}

# Succeeds when the app can reach the API with the current sign-in. Listing a model costs nothing.
check_api() {
  local env_file=()
  [[ -f "$ENV_FILE" ]] && env_file=(--env-file "$ENV_FILE")
  uv run --quiet --frozen --no-dev --project "$ROOT" ${env_file[@]+"${env_file[@]}"} python -I -c '
import sys
import anthropic
from exif_dater.claude import DEFAULT_MODEL, has_credentials

client = anthropic.Anthropic()
if not has_credentials(client):
    sys.exit("no Claude credentials found")
try:
    client.models.retrieve(DEFAULT_MODEL)
except anthropic.AnthropicError as error:
    sys.exit(f"the API check failed: {error}")
print(f"  signed in, and {DEFAULT_MODEL} is available")
'
}

# "ant" is also the name of Apache's Java build tool, which can't sign in.
claude_cli_ready() {
  have ant && ! ant --version 2>&1 | grep -qi 'apache ant'
}

install_claude_cli() {
  local arch sum work result=1
  case "$(uname -s)-$(uname -m)" in
    Linux-x86_64) arch=amd64 sum=$ANT_SHA256_AMD64 ;;
    Linux-aarch64 | Linux-arm64) arch=arm64 sum=$ANT_SHA256_ARM64 ;;
    *)
      warn "Install the ant CLI yourself, then run this wizard again."
      open_url "https://platform.claude.com/docs/en/cli-sdks-libraries/cli/quickstart"
      return 1
      ;;
  esac
  confirm "Download Anthropic's ant CLI $ANT_VERSION from GitHub into ~/.local/bin?" || return 1
  work=$(mktemp -d)
  if curl -fsSL -o "$work/ant.tar.gz" \
    "https://github.com/anthropics/anthropic-cli/releases/download/v$ANT_VERSION/ant_${ANT_VERSION}_linux_$arch.tar.gz" &&
    printf '%s  %s\n' "$sum" "$work/ant.tar.gz" | sha256sum --check --status &&
    tar -xzf "$work/ant.tar.gz" -C "$work" ant &&
    mkdir -p "$HOME/.local/bin" &&
    install -m 755 "$work/ant" "$HOME/.local/bin/ant"; then
    result=0
  else
    warn "The download failed or didn't match its checksum, so nothing was installed."
  fi
  rm -rf "$work"
  return "$result"
}

forget_saved_key() {
  local kept
  kept=$(grep -v '^ANTHROPIC_API_KEY=' "$ENV_FILE" || true)
  if [[ -n "$kept" ]]; then
    printf '%s\n' "$kept" > "$ENV_FILE"
  else
    rm -f "$ENV_FILE"
  fi
}

sign_in_with_browser() {
  claude_cli_ready || install_claude_cli || return 1
  local options=()
  if [[ "$(uname -s)" == Linux && -z "${DISPLAY:-}${WAYLAND_DISPLAY:-}" ]]; then
    options=(--no-browser)
  fi
  step "Sign in on the page that opens, then pick your organization and workspace."
  ant auth login ${options[@]+"${options[@]}"} || return 1
  if _existing ANTHROPIC_API_KEY >/dev/null; then
    warn "A saved API key would be used instead of this sign-in."
    if confirm "Delete the saved key from $ENV_FILE?"; then forget_saved_key; fi
  fi
}

save_api_key() {
  open_url "https://platform.claude.com/settings/keys"
  step "Choose 'Create key' and name it exif-dater."
  step "Pick an expiration, link it to yourself and select one workspace."
  step "Copy the key. It starts with sk-ant- and is shown only once."
  note "It will be saved, readable only by you, in $ENV_FILE"
  while :; do
    ask_secret ANTHROPIC_API_KEY "Paste the key (input is hidden, Enter alone skips):" || return 1
    [[ -z "$ANTHROPIC_API_KEY" ]] && return 1
    [[ "$ANTHROPIC_API_KEY" == sk-ant-* ]] && break
    warn "That doesn't start with sk-ant-, so it wasn't saved. Try again."
  done
  mkdir -p "$(dirname "$ENV_FILE")"
  chmod 700 "$(dirname "$ENV_FILE")"
  write_env ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
  chmod 600 "$ENV_FILE"
}

run_wizard() {

TOTAL_STAGES=6

banner "EXIF Dater setup"

stage "Photo tools: ImageMagick and ExifTool"
local packages=()
have magick || packages+=(imagemagick)
have exiftool || packages+=(libimage-exiftool-perl)
if (( ${#packages[@]} )); then apt_install "${packages[@]}" || true; fi
if have magick; then done_ok "ImageMagick"; else
  todo "Install ImageMagick 7, which provides the magick command: https://imagemagick.org"
fi
if have exiftool; then done_ok "ExifTool"; else
  todo "Install ExifTool: https://exiftool.org"
fi
pause

stage "Node.js 20 or later, for npx"
node_ready || apt_install nodejs npm || true
if node_ready; then done_ok "Node.js $(node --version)"; else
  todo "Install Node.js 20 or later: https://nodejs.org/en/download"
fi
pause

stage "uv, which runs the Python app"
if ! have uv && confirm "Download and run the official installer from https://astral.sh/uv/install.sh?"; then
  curl -LsSf https://astral.sh/uv/install.sh | sh || warn "the uv installer failed"
fi
if have uv; then done_ok "$(uv --version)"; else
  todo "Install uv: https://docs.astral.sh/uv/"
fi
pause

stage "Claude account and billing"
say "Dating photos uses the Claude API, which is billed separately per request."
say "100 photos cost roughly \$0.06 with the default model."
if confirm "Open the Claude Console to sign in or create an account and check billing?"; then
  open_url "https://platform.claude.com/settings/billing"
  step "Sign in, or create an account if you don't have one."
  step "Make sure there is credit: buy some, or claim any your Claude plan includes."
  note "Enter payment details only on that page. This wizard never asks for them."
fi
pause

stage "Sign in to the Claude API"
local change=yes method=""
if [[ -n "$SHELL_KEY" ]]; then
  warn "ANTHROPIC_API_KEY is set in your shell. It overrides any sign-in made here."
fi
if have uv; then
  say "Checking for an existing sign-in (the first run downloads the app's packages)..."
  if check_api 2>/dev/null; then
    confirm "Set up a different sign-in?" || change=""
  fi
fi
if [[ -n "$change" ]]; then
  say "1) Sign in with your browser (recommended: no key to copy, short-lived token)"
  say "2) Paste an API key"
  say "Enter alone skips this stage."
  ask SIGN_IN_METHOD "Choose 1 or 2:"
  method="$SIGN_IN_METHOD"
  case "$method" in
    1) sign_in_with_browser || warn "browser sign-in didn't finish" ;;
    2) save_api_key || warn "no key saved" ;;
    *) note "skipped" ;;
  esac
fi
pause

stage "Check everything"
if ! have uv; then
  todo "Run this wizard again after installing uv, to check the sign-in"
elif check_api; then
  done_ok "Claude API"
else
  todo "Sign in to the Claude API: run this wizard again"
fi
note "Google Photos needs no key: the app doesn't connect to it. Upload the dated copies yourself."
pause

if (( ${#SKIPPED[@]} )); then
  printf '\n'
  warn "Setup is incomplete. Still to do:"
  local item
  for item in "${SKIPPED[@]}"; do note "  - $item"; done
  return 1
fi
finish
say "Date your photos with:"
say "  cd $(printf '%q' "$ROOT") && npx . <photo folder>"
}

run_wizard "$@"; exit
